INSERT INTO `t_report_calculation_formulas` VALUES (2406, '2447', '浓度', '光谱浓度', 'mol/L', '吸光度', 'abs', '取样量', 'm', '稀释倍数', 't', '', NULL, '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '浓度=410abs/m*t', 'data:image/png;base64,', '大发发地方');
