INSERT INTO `t_report_calculation_formulas` VALUES (2408, '2449', 'X1', '样品中多糖含量', 'mg/L或mg/kg', '标准曲线查的样品浓度(μg/mL)', 'C1', '标准曲线查的空白浓度(μg/mL)', 'C2', '待测样品定容体积(mL)', 'V1', '稀释倍数，本方法为5', 'D1', '移取液体的体积(mL)', 'V2', '称取固体的质量（g）', 'm1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X1=（C1-C2）*V1*D1/(V2或m1)', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2409, '2451', 'X3', '样品的芦荟苷含量', 'mg/L或mg/kg', '', '', '所移取的0.5%醋酸镁甲醇溶液的体积(mL)', 'V5', '所移取的CCl4萃取液的体积(mL)', 'V6', '用CCl4定容的体积', 'V7', '移取液体的体积(mL)', 'V8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X3=(41.67*A1*V5*V7)/(V6*V8)', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2410, '2452', 'X4', '样品的Ο-乙酰基含量', 'mg/L或mg/kg', '曲线上查得样品溶液的Ο-乙酰基浓度，mg/mL', 'C4', '曲线上查得空白样品溶液的Ο-乙酰基浓度，mg/mL', 'C5', '待测样品定容体积(mL)', 'V9', '移取液体样品的体积，mL', 'V10', '称取固体样品的质量，g', 'm4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X4=（C4-C5)*V9*1000/（V10或m4）', 'data:image/png;base64,', NULL);
