INSERT INTO `t_report_calculation_formulas` VALUES (2493, '2535', 'w2', 'IMP的质量分数', '%', '试样溶液在250nm 处测得的吸光度;', 'A', '试样溶液在280nm 处测得的吸光度;', 'B', '试样的称样量,单位为克(g);', 'm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'w2=(A-1.462*B)*342.18/(m*5)*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2494, '2535', 'w3', 'GMP的质量分数', '%', '试样溶液在250nm 处测得的吸光度;', 'A', '试样溶液在280nm 处测得的吸光度;', 'B', '试样的称样量,单位为克(g);', 'm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'w3=(7.976×B-A)*62.55/(m*5)*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2495, '2535', 'X1', 'IMP混合比', '%', '试样中IMP的质量分数,%;', 'w2', '试样中 GMP的质量分数,%;', 'w3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X1=w2/(w2+w3)*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2496, '2535', 'X2', 'GMP混合比', '%', '试样中IMP的质量分数,%;', 'w2', '试样中 GMP的质量分数,%;', 'w3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X1=w3/(w2+w3)*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2497, '2536', 'X3', '呈味核苷酸二钠含量', 'g/100g', '试样溶液在250nm 处测得的吸光度;', 'A', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'X3=(A*530*2000)/(m3*11950*1000)*100', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2498, '2538', 'E(1%1cm)', '吸光值(1%1cm)460nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '稀释倍数', 'f', '试样的质量，g', 'm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(1%1cm)=A*f/（m*100)', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2499, '2539', 'E(1%1cm)', '色价以被测试样液浓度为 1 %、用 1 cm 比色皿、在 580 nm~620 nm 范围内最大吸收波长处测得的吸\n光度', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '被测试样液浓度的数值，单位为克每毫升（g/mL）', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(1%1cm)=A/c*1/100', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2500, '2540', 'E(0.1%1cm)', '吸光值(0.1%1cm)610nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '被测试样液浓度的数值，单位为克每毫升（g/mL）', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(0.1%1cm)=A/(c*1000)', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2501, '2541', 'E(1%1cm)', '吸光值(1%1cm)535nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '甜菜红溶液浓度的数值，%', 'c', '比色杯溶液的厚度，单位cm', 'L', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(0.1%1cm)=A/(c*L)', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2502, '2542', 'E(1%1cm)', '吸光值(1%1cm)495±10nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '被测试样液浓度的数值，单位为克每毫升（g/mL）', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(1%1cm)=A/c*1/100', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2503, '2543', 'ω1', '亮蓝含量的质量分数', '%', '试样溶液的吸光度', 'A1', '亮蓝对照品的质量,单位为克(g);', 'm0', '亮蓝对照品溶液的吸光度;', 'A0', '试样的质量,单位为克(g);', 'm1', '亮蓝对照品的质量分数(按 A.4.1测定),%。', 'ω0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=（A1×m0)/(A0*m1)*ω0*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2504, '2544', 'ω1', '胭脂红含量的质量分数', '%', '试样溶液的吸光度', 'A1', '胭脂红对照品的质量,单位为克(g);', 'm0', '胭脂红对照品溶液的吸光度;', 'A0', '试样的质量,单位为克(g);', 'm1', '胭脂红对照品的质量分数(按 A.4.1测定),%。', 'ω0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=（A1×m0)/(A0*m1)*ω0*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2505, '2545', 'ω1', '诱惑红含量的质量分数', '%', '试样溶液的吸光度', 'A1', '诱惑红对照品的质量,单位为克(g);', 'm0', '诱惑红对照品溶液的吸光度;', 'A0', '试样的质量,单位为克(g);', 'm1', '诱惑红对照品的质量分数(按 A.4.1测定),%。', 'ω0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=（A1×m0)/(A0*m1)*ω0*100%', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2506, '2546', 'ω1', '苋菜红含量的质量分数', '%', '苋菜红试样溶液的吸光度', 'A', '苋菜红标准品的质量,单位为克(g);', 'm0', '苋菜红标准品溶液的吸光度;', 'A0', '试样的质量,单位为克(g);', 'm', '苋菜红标准品的质量分数,%。', 'ω0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=（A×m0)/(A0*m)*ω0', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2507, '2547', 'ω1', '柠檬黄含量的质量分数', '%', '柠檬黄试样溶液的吸光度', 'A', '柠檬黄标准品的质量,单位为克(g);', 'm0', '柠檬黄标准品溶液的吸光度;', 'A0', '试样的质量,单位为克(g);', 'm', '柠檬黄标准品的质量分数,%。', 'ω0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ω1=（A×m0)/(A0*m)*ω0', 'data:image/png;base64,', NULL);
INSERT INTO `t_report_calculation_formulas` VALUES (2508, '2548', 'E(1%1cm)', '吸光值(1%1cm)440±5nm', '(g/100mL)⁻¹·cm⁻¹', '实测试样溶液的吸光值', 'A', '被测试样液浓度的数值，单位为克每毫升（g/mL）', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E(1%1cm)=A/c*1/100', 'data:image/png;base64,', NULL);
